  {
   "cohort_id": "top-volume-fha",
   "title": "Twenty largest FHA lenders by modelled volume, 2025",
   "question": "Which of the biggest FHA lenders sit above or below the denial rate their own applicant mix predicts?",
   "lei_count": 20,
   "universe": "FHA forward loans, 2025; lenders ranked by applications inside the expectation model"
  },
  {
   "cohort_id": "high-coverage-only",
   "title": "Lenders whose profile coverage exceeds 90%",
   "question": "If we keep only the lenders the model can see clearly, does the picture change?",
   "lei_count": 25,
   "universe": "FHA forward loans, 2025; profile_coverage_pct >= 90 only — the cohort that exists to test whether coverage drives the result"
  },
  {
   "cohort_id": "above-expectation",
   "title": "Every lender whose 95% interval lies entirely above 1.0",
   "question": "Which lenders deny more than their own mix predicts, with the interval excluding parity?",
   "lei_count": 25,
   "universe": "FHA forward loans, 2025; flag=above_expectation_ci_excludes_1 and coverage >= 70"
  },
  {
   "cohort_id": "depository-institutions",
   "title": "FHA lenders that are also FDIC-insured depositories",
   "question": "Do banks behave differently from independent mortgage banks on the same program?",
   "lei_count": 25,
   "universe": "FHA forward loans, 2025, intersected with the FDIC BankFind institution list via fuzzy name match (join_type=fuzzy_name, confidence >= 0.80)"
  },
  {
   "cohort_id": "screening-only",
   "title": "The cohort the model cannot see well",
   "question": "What does a list look like when coverage is too thin to claim a signal?",
   "lei_count": 15,
   "universe": "FHA forward loans, 2025; rows flagged screening_only_insufficient_coverage — published so the limits of the screen are as visible as its findings"
  }
 ],
 "next_step": {
  "code": "RUN_A_COHORT",
  "how": "call run_cohort with one of these cohort_id values; no upload and no license needed for the aggregate view"
 },
 "disclaimer": "This is a public-data screening signal. It is not evidence of misconduct, discrimination, causation, legal violation, credit approval probability or an individual lending decision. Rows flagged screening_only_insufficient_coverage must not be read as elevated risk."
}

{
